  package     com . digi . xbee . api . packet ;   import   java . util . HashMap ;  import      com . digi . xbee . api . utils . ByteUtils ;  import      com . digi . xbee . api . utils . HexUtils ;   public enum APIFrameType  {  TX_64  ( 0x00 , "TX (Transmit) Request 64-bit address" ) ,  TX_16  ( 0x01 , "TX (Transmit) Request 16-bit address" ) ,  AT_COMMAND  ( 0x08 , "AT Command" ) ,  TRANSMIT_REQUEST  ( 0x10 , "Transmit Request" ) ,  REMOTE_AT_COMMAND_REQUEST  ( 0x17 , "Remote AT Command Request" ) ,  RX_64  ( 0x80 , "RX (Receive) Packet 64-bit Address" ) ,  RX_16  ( 0x81 , "RX (Receive) Packet 16-bit Address" ) ,  RX_IO_64  ( 0x82 , "IO Data Sample RX 64-bit Address Indicator" ) ,  RX_IO_16  ( 0x83 , "IO Data Sample RX 16-bit Address Indicator" ) ,  AT_COMMAND_RESPONSE  ( 0x88 , "AT Command Response" ) ,  TX_STATUS  ( 0x89 , "TX (Transmit) Status" ) ,  TRANSMIT_STATUS  ( 0x8B , "Transmit Status" ) ,  RECEIVE_PACKET  ( 0x90 , "Receive Packet" ) ,  IO_DATA_SAMPLE_RX_INDICATOR  ( 0x92 , "IO Data Sample RX Indicator" ) ,  REMOTE_AT_COMMAND_RESPONSE  ( 0x97 , "Remote Command Response" ) ,  GENERIC  ( 0xFF , "Generic" )  ;   private final  int  idValue ;   private final String  name ;   private static final  HashMap  < Integer , APIFrameType >  lookupTable =  new  HashMap  < Integer , APIFrameType >  ( ) ;  static  {  for ( APIFrameType type :  values  ( ) )   lookupTable . put  (  type . getValue  ( ) , type ) ; }  APIFrameType  (   int idValue ,  String name )  {    this . idValue = idValue ;    this . name = name ; }   public static APIFrameType get  (   int value )  {  APIFrameType  type =  lookupTable . get  ( value ) ;  return type ; }   public  int getValue  ( )  {  return idValue ; }   public String getName  ( )  {  return name ; }    @ Override public String toString  ( )  {  return    "(" +  HexUtils . byteArrayToHexString  (  ByteUtils . intToByteArray  ( idValue ) ) + ") " + name ; } }